-			rolling_buffer_clear(roll);
-			return -ENOMEM;
-		}
-		fq->prev = roll->head;
-		if (!roll->tail)
-			roll->tail = fq;
-		else
-			roll->head->next = fq;
-		roll->head = fq;
-
