+ 		fprintf(stderr, "malloc() failed\n");
+ 		return NULL;
+ 	}
+ 
 -	for (ptr = buf; ptr < buf + size; ptr += PAGE_SIZE)
 +	for (ptr = buf; ptr < buf + size; ptr += page_size)
  		*ptr = 0;
  
+ 	return buf;
+ }
+ 
+ int alloc_anon(const char *cgroup, void *arg)
