-static void hclge_rfs_filter_expire(struct hclge_dev *hdev)
-{
-#ifdef CONFIG_RFS_ACCEL
-	struct hnae3_handle *handle = &hdev->vport[0].nic;
-	struct hclge_fd_rule *rule;
