-
-		hclge_clear_fd_rules_in_list(hdev, clear_list);
-	}
-
-	hclge_sync_fd_user_def_cfg(hdev, false);
-
-	hclge_sync_fd_list(hdev, &hdev->fd_rule_list);
-}
