 	unsigned long min, max, util = scx_cpuperf_target(sg_cpu->cpu);

 	if (!scx_switched_all())
-		util += cpu_util_cfs_boost(sg_cpu->cpu);
+		util += cpu_util_cfs(sg_cpu->cpu);
